class TreeNode:
    def __init__(self, val=0, left=None, right=None, nextRight=None):
        self.val = val
        self.left = left
        self.right = right
        self.nextRight = nextRight

def connect(root):
    if not root:
        return

    queue = [root]
    while queue:
        size = len(queue)
        for i in range(size):
            node = queue.pop(0)
            if i < size - 1:
                node.nextRight = queue[0]
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

def level_order_traversal(root):
    if not root:
        return []
    result = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        result.append(node.val)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return result

def inorder_traversal(root):
    if not root:
        return []
    return inorder_traversal(root.left) + [root.val] + inorder_traversal(root.right)

import sys
from collections import deque

input = sys.stdin.read().strip().split()
nodes = [TreeNode(int(x)) if x != 'null' else None for x in input]
root = nodes[0]
index = 1
queue = deque([root])
while queue and index < len(nodes):
    node = queue.popleft()
    if node:
        node.left = nodes[index]
        queue.append(node.left)
        index += 1
        if index < len(nodes):
            node.right = nodes[index]
            queue.append(node.right)
            index += 1

connect(root)
level_order = level_order_traversal(root)
inorder = inorder_traversal(root)
print(' '.join(map(str, level_order)))
print(' '.join(map(str, inorder)))
